        "4. 深い傷は適切な粗さの工程へ戻る。",
        "5. 柔らかい工具ほど稜線を丸める可能性を意識する。",
        "6. 平面は硬い支持体で作る。",
        "7. 曲面は曲率に合う支持体を使う。",
        "8. 凹部入口を大径工具で丸めない。",
        "9. バフは形状形成工具にしない。",
        "10. 研磨材の色で性能を判断しない。",
        "11. 粒度規格の違いを混同しない。",
        "12. 粗・細バフを分離する。",
        "13. 素材別コンタミ管理を決める。",
        "14. 切れない工具を圧力で使い続けない。",
        "15. rpm だけでなく周速を考える。",
        "16. 工具の最大許容回転数を超えない。",
        "17. 接触幅・圧力・滞留時間を管理する。",
        "18. 発熱を仕上げ条件の一つとして扱う。",
        "19. 鋳巣を周囲研磨だけで追い込まない。",
        "20. ロー目色差を研磨で隠そうとしない。",
        "21. 中古品は新品と同じ傷除去量を目標にしない。",
        "22. 深い打痕は肉盛り・バニシング等も検討する。",
        "23. 爪・刻印・ミル・彫りは設計情報である。",
        "24. 石留め前にアクセス困難部を仕上げる。",
        "25. 石付き品は石・処理・接着を確認する。",
        "26. 硬度だけで宝石の洗浄安全性を判断しない。",
        "27. 超音波は全品一律に使わない。",
        "28. プラチナはバニシングという選択肢を持つ。",
        "29. Pt950 刻印だけで合金系を決めない。",
        "30. K18 刻印だけで研磨性を固定しない。",
        "31. WG は必ずロジウムとは限らない。",
        "32. めっきは深傷隠しではない。",
        "33. めっき前に機械仕上げを完成させる。",
        "34. 脱脂・活性化を独立工程として管理する。",
        "35. めっき後に強いバフを前提にしない。",
        "36. マット仕上げも工程標準化する。",
        "37. ブラストは圧力・距離・粒子・時間を管理する。",
        "38. 古美・パティナを傷と誤認しない。",
        "39. 磁気研磨の一般化を避ける。",
        "40. マスフィニッシングは試験片で条件出しする。",
        "41. 洗浄後の表面を完成判定する。",
        "42. 複数方向の照明で検品する。",
        "43. 鏡面は反射像の歪みを見る。",
        "44. 加工前写真を品質資料にする。",
        "45. 寸法を複数位置で測る。",
        "46. 必要時に加工前後重量を記録する。",
        "47. 再作業理由を工程改善データとして残す。",
        "48. 粉じんは発生源で捕集する。",
        "49. 貴金属回収と安全衛生を両立させる。",
        "50. 良い仕上げは最小材料除去で設計表面を再現する。",
        "Step 1 材料：品位ではなく、可能な限り合金系・鋳造/加工材・めっきの有無まで確認。",
        "Step 2 構造：爪・ベゼル・ヒンジ・中空・薄肉・ロー目・過去修理を確認。",
        "Step 3 石：石種・処理・亀裂・接着・超音波/スチーム可否を確認。",
        "Step 4 欠陥：深傷・ピット・鋳巣・打痕を「削るべきか、修理すべきか」に分類。",
        "Step 5 形状：平面・曲率・稜線・寸法を作ってから細研磨へ。",
        "Step 6 傷置換：前工程傷を完全に消してから次へ。残ったら戻る。",
        "Step 7 表面：鏡面／ヘアライン／サテン／梨地／古美の目標を再現。",
        "Step 8 洗浄/めっき：石と素材に適合する洗浄。めっきは前処理を独立管理。",
        "Step 9 検品：形状→構造→表面→石→可動部→刻印の順で確認。",
        "Step 10 記録：写真、寸法、使用工具、再作業、最終判定を記録。"
