          "石留め（stone setting）は、宝石を枠に押し込んで動かなくする作業ではない。石の形状・耐久性・処理を診断し、地金側に石輪郭へ適合する座（bearing / seat）を形成し、必要な地金だけを弾塑性的に移動させ、複数方向の抜け止めと位置拘束を作り、仕上げ・洗浄・通常使用後まで保持性能を残す製造工程である。完成直後にピンセットで動かないだけでは不十分である。通常使用では、衝撃、繰返し微小変形、衣服との擦れ、リングの楕円化、摩耗、洗浄振動、後工程の研磨が加わる。良い石留めはこれらを受けても「石・保持地金・周辺構造の三者が急速に破綻しない」よう設計される。重要：石留めの品質は「力の強さ」より、座の適合、残存断面、力の方向、摩耗余裕、検査で決まる。"
