        "35. 圧力を上げて切れ味不足を補わない。",
        "36. 高 rpm を品質の代用にしない。",
        "37. 温度上昇はドップと石の両方を見る。",
        "38. 粗粒とポリッシュ用具を分離する。",
        "39. ワイプやスポイトもコンタミ源として管理する。",
        "40. ランダム深傷はまずコンタミを疑う。",
        "41. edge rounding は最終艶より重大な形状不良になり得る。",
        "42. orange peel を単一原因で決めつけない。",
        "43. 特定方向だけ磨けない時は異方性を疑う。",
        "44. 石英系の曇りはセリア量だけ増やして直さない。",
        "45. コランダムは硬いが割れないわけではない。",
        "46. エメラルドは亀裂・充填を前提に保守的に扱う。",
        "47. トルマリンは多色性と熱を同時に見る。",
        "48. トパーズは Mohs 8 でも劈開が重要。",
        "49. ジルコンは高 RI でも edge 耐久を軽視しない。",
        "50. オパールは含水・多孔性・複合構造を確認する。",
        "51. ターコイズ等の多孔質石へ研磨剤を染み込ませない。",
        "52. Jade は単結晶石の研磨論をそのまま当てない。",
        "53. ダイヤモンド加工を一般色石と同一工程にしない。",
        "54. 合成石でも内部応力や方位を確認する。",
        "55. ガラスは結晶でないが熱衝撃と表面下損傷を持つ。",
        "56. リカット前に得られる価値と失う重量を比較する。",
        "57. 欠けを全部消すことが常に正解ではない。",
        "58. キャリブレートでは寸法優先を明示する。",
        "59. カボションのドームを一発で丸めない。",
        "60. カボションの輪郭とショルダーを先に作る。",
        "61. 現象石の中心をドーム頂点へ正しく置く。",
        "62. 洗浄後の表面を完成判定する。",
        "63. 超音波を自動工程にしない。",
        "64. 完成検査は複数照明方向で行う。",
        "65. 反射像で facet flatness を見る。",
        "66. 重量・寸法・meet・光学を同時に記録する。",
        "67. 失敗条件も作業票に残す。",
        "68. SDS/TDS と機器マニュアルを優先する。",
        "69. 工房の安全・粉じん管理を技能の一部と考える。",
        "70. 良い研磨とは、最小限の損失で石の光学・色・耐久性を意図した状態にすることである。"
