Object.entries(MASTER_TOOL_GUIDE_ADDITIONS_V467).forEach(([toolId, addition]) => {
  const tool = WORKSHOP_TOOLS[toolId];
  if (!tool) return;
  if (addition.description) tool.description = addition.description;
  if (addition.detail) tool.detail = addition.detail;
  if (!tool.guide) tool.guide = { overview: tool.detail || tool.description || '', sections: [] };
  if (addition.overview) tool.guide.overview = addition.overview;
  tool.guide.sections = [...(tool.guide.sections || []), ...(addition.sections || [])];
  tool.guide.references = [...new Set([...(tool.guide.references || []), ...(addition.references || [])])];
  tool.guide.revision = '2026-07-31';
  tool.guide.scope = '構造・選定・実作業・精度管理・不良診断・安全・保守・記録';
});


Object.values(WORKSHOP_TOOLS).forEach((tool) => {
  if (!tool.guide) return;
  tool.guide.sections.push(
    {
      title: `${tool.name}を導入・選定する時の確認`,
      paragraphs: [
        `${tool.name}は名称や外観だけで選ばず、想定する地金・宝石・製品寸法、必要精度、連続使用時間、設置場所、電源・ガス・換気、対応する消耗品と治具まで含めて選定します。価格が高い機種でも、作業範囲や保守体制が合わなければ品質と安全は安定しません。`,
        `購入前にはメーカーの最新仕様、取扱説明書、保証、交換部品、校正・修理窓口を確認し、実際の作業を想定した試験片で操作性と仕上がりを比較します。中古品は摩耗、改造、欠品、安全装置、電気・ガス系統の状態を専門家が確認します。`
      ],
      points: [
        '必要能力と最大能力の間に余裕を持たせる',
        '本体だけでなく治具・消耗品・集塵・保護具の費用を含める',
        '作業者の手の大きさ、姿勢、利き手、作業台との相性を確認する',
        'メーカーが想定しない改造や用途外使用を前提にしない',
        '導入時の基準状態を写真・測定値・試験片で保存する'
      ]
    },
    {
      title: `${tool.name}の作業記録と再現性`,
      paragraphs: [
        `熟練者の感覚を再現可能な技術にするため、${tool.name}を使用した案件では、対象素材、寸法、工具・先端・番手、設定値、作業順、加工時間、途中測定、最終検査、異常の有無を記録します。設定値がない手工具でも、保持位置、力の方向、回数、基準面、仕上げ順を言語化できます。`,
        `良好な結果だけでなく、刃折れ、傷、変形、発熱、石の緩み、寸法超過などの失敗条件も残します。記録を工具交換、材料ロット、修理、校正履歴と結び付けると、個人差と設備劣化を切り分け、次回の見積り・納期・品質基準へ反映できます。`
      ],
      points: [
        '案件番号・作業者・日時を記録する',
        '作業前後の写真、重量、主要寸法を必要に応じて残す',
        '使用した工具番号、消耗品ロット、設定値を紐付ける',
        '異常時は継続せず、原因と処置を記録する',
        '定期的に記録を見直し、標準作業と交換基準を更新する'
      ]
    }
  );
});


